#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void setup() {
  USB.begin();
  Keyboard.begin();
  delay(1000);            // 1) ожидание перечисления USB (минимум надёжного)

  // Win + R — открываем диалог «Выполнить»
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  Keyboard.releaseAll();
  delay(200);             // 2) диалог «Выполнить» появляется почти мгновенно

  // Всё одной строкой: cmd с /k (не закрывается) + color 2 + dir /s
  Keyboard.print("cmd /k color 2 & dir /s");
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
  delay(300);             // 3) cmd запускается, команды идут в очередь ввода

  // Alt + Enter — полноэкранный режим консоли
  Keyboard.press(KEY_LEFT_ALT);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
}

void loop() {}
